thm-hyp(
    Logic.and(Type.annotation(@E, Set(A@Topology.ctxt.AB)), Set.subset(E, X@Topology.ctxt.X)),
    Logic.iff(
        Topology.continuousMap(f@Topology.ctxt.f, E, Y@Topology.ctxt.Y),
        Logic.forall-typed(
            @V,
            Set(B@Topology.ctxt.AB),
            Logic.implies(
                Topology.openSet[text](V, τ_Y@Topology.ctxt.tauY),
                Topology.openSet[text](Set.preim(f@Topology.ctxt.f, V), τ_X@Topology.ctxt.tauX)
            )
        )
    )
)
